import json
with open('/app/resources/treasury_bulletin_2013_06.json') as f:
    data = json.load(f)

# Search for exchange stabilization in the content
def search_elements(elements, target):
    results = []
    for el in elements:
        if el.get('content') and target.lower() in el['content'].lower():
            results.append(el)
        if 'elements' in el:
            results.extend(search_elements(el['elements'], target))
    return results

# Let's look at the structure
def print_structure(elements, depth=0):
    for el in elements:
        print("  " * depth + f"Type: {el.get('type')}")
        if el.get('content'):
            content = str(el.get('content'))[:100]
            print("  " * depth + f"Content: {content}...")
        if 'elements' in el and depth < 3:
            print_structure(el['elements'], depth + 1)

# Just search the text content
def search_content(elements, text, results=None):
    if results is None:
        results = []
    for el in elements:
        if el.get('content') and text.lower() in str(el.get('content')).lower():
            results.append(el['content'])
        if 'elements' in el:
            search_content(el['elements'], text, results)
    return results

# Let's search
results = search_content(data['document']['elements'], 'December 31, 2013')
for r in results:
    print(r[:500])
    print("---")
EOF
